import { useState, useEffect, useRef } from "react";
import { Card } from "./components/ui/card";
import { ScrollArea } from "./components/ui/scroll-area";
import { ChatMessage } from "./components/ChatMessage";
import { ChatInput } from "./components/ChatInput";
import { ChatHeader } from "./components/ChatHeader";
import { toast } from "sonner@2.0.3";

export default function App() {
  const [messages, setMessages] = useState([
    {
      id: "1",
      text: "Hello! I'm your AI assistant. How can I help you today? 💙",
      isUser: false,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userName, setUserName] = useState("");
  const scrollAreaRef = useRef(null);

  const scrollToBottom = () => {
    if (scrollAreaRef.current) {
      const scrollContainer = scrollAreaRef.current.querySelector('[data-radix-scroll-area-viewport]');
      if (scrollContainer) {
        scrollContainer.scrollTop = scrollContainer.scrollHeight;
      }
    }
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = (text) => {
    const userMessage = {
      id: Date.now().toString(),
      text,
      isUser: true,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMessage]);
    setIsTyping(true);

    // Simulate AI response
    setTimeout(() => {
      const responses = [
        "That's an interesting question! 🤔 Let me help you with that.",
        "I love helping with professional conversations! 💼 What else would you like to know?",
        "Great message! ✨ I'm here to assist you with anything you need.",
        "Thanks for sharing! 🌟 This clean interface makes chatting efficient and pleasant!",
        "I appreciate your message! 💙 How else can I help you today?"
      ];

      const aiMessage = {
        id: (Date.now() + 1).toString(),
        text: responses[Math.floor(Math.random() * responses.length)],
        isUser: false,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, aiMessage]);
      setIsTyping(false);
    }, 1500);
  };

  const handleLogin = (email, password) => {
    // Simulate login
    setIsLoggedIn(true);
    setUserName(email.split('@')[0]);
    toast.success("Successfully logged in! Welcome back! 🎉");
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserName("");
    toast.success("Successfully logged out! See you soon! 👋");
  };

  const handleRegister = (email, password, name) => {
    // Simulate registration
    setIsLoggedIn(true);
    setUserName(name);
    toast.success("Account created successfully! Welcome aboard! 🚀");
  };

  const handleWordLookup = (word) => {
    toast.success(`Looking up "${word}" in the dictionary! 📚`);
  };

  return (
    <div className="h-screen bg-gradient-to-br from-slate-600 via-blue-600 to-gray-700 p-4">
      <div className="max-w-4xl mx-auto h-full">
        <Card className="h-full flex flex-col shadow-2xl border-0 overflow-hidden">
          <ChatHeader
            isLoggedIn={isLoggedIn}
            userName={userName}
            onLogin={handleLogin}
            onLogout={handleLogout}
            onRegister={handleRegister}
            onWordLookup={handleWordLookup}
          />

          <ScrollArea ref={scrollAreaRef} className="flex-1 p-4 bg-gradient-to-b from-white to-slate-50">
            <div className="space-y-4">
              {messages.map((message) => (
                <ChatMessage
                  key={message.id}
                  message={message.text}
                  isUser={message.isUser}
                  timestamp={message.timestamp}
                />
              ))}

              {isTyping && (
                <div className="flex gap-3 mb-4">
                  <div className="w-8 h-8 rounded-full bg-gradient-to-r from-blue-500 to-slate-600 flex items-center justify-center text-sm text-white">
                    AI
                  </div>
                  <div className="bg-gradient-to-r from-gray-100 to-gray-200 rounded-lg px-3 py-2">
                    <div className="flex gap-1">
                      <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-slate-600 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                      <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </ScrollArea>

          <ChatInput
            onSendMessage={handleSendMessage}
            disabled={isTyping}
            placeholder="Type your message..."
          />
        </Card>
      </div>
    </div>
  );
}
